const userPhotoByClientFileID = `-- name: UserPhotoByClientFileID :one
SELECT user_id, file_id, client_file_id, created_at
FROM user_photos
WHERE user_id = $1 AND client_file_id = $2
`

type UserPhotoByClientFileIDParams struct {
	UserID       int64
	ClientFileID int64
}

// UserPhotoByClientFileID resolves an owner's entry by its upload identity.
// This is the read that makes a completed retry return the identity the key
// already bought, with no parts, no allocation and no new charge.
func (q *Queries) UserPhotoByClientFileID(ctx context.Context, arg UserPhotoByClientFileIDParams) (UserPhoto, error) {
	row := q.db.QueryRow(ctx, userPhotoByClientFileID, arg.UserID, arg.ClientFileID)
	var i UserPhoto
	err := row.Scan(
		&i.UserID,
		&i.FileID,
		&i.ClientFileID,
		&i.CreatedAt,
	)
	return i, err
}
